/**
 * Petshop Uzsakymu Numeracija v1.0 (woocommerce_order_number filtras)
 *
 * S1663 (Raimio sprendimas 2026-09-09): klientui rodomi nuoseklus uzsakymu
 * numeriai nuo 1000 (vidinis ID lieka 35xxx — Paysera/siuntos/DB nesikeicia).
 * Counter `petshop_order_counter` = KITAS numeris (kaip AVPN/KR/IAPV/PPK).
 * Priskiriama kuriant uzsakyma; checkout-draft praleidziamas (numeriu
 * nedeginam juodrasciams) — priskiriama isejus is draft.
 * Seni uzsakymai be metos rodo savo ID (35868–35876 palikti — Raimio sprendimas).
 */
function petshop_priskirti_uzsakymo_nr( $order ) {
	if ( ! $order instanceof WC_Order || 'shop_order' !== $order->get_type() ) return;
	if ( $order->get_meta( '_ps_order_number' ) ) return;
	if ( in_array( $order->get_status(), array( 'checkout-draft', 'auto-draft' ), true ) ) return;
	global $wpdb;
	$wpdb->query( "UPDATE {$wpdb->options} SET option_value = LAST_INSERT_ID(option_value + 1) WHERE option_name = 'petshop_order_counter'" );
	$naujas = (int) $wpdb->get_var( 'SELECT LAST_INSERT_ID()' );
	if ( $naujas < 2 ) return; // opcijos nera — geriau ID nei 0/1
	$order->update_meta_data( '_ps_order_number', $naujas - 1 );
	$order->save();
}
add_action( 'woocommerce_new_order', function( $order_id, $order = null ) {
	petshop_priskirti_uzsakymo_nr( $order ? $order : wc_get_order( $order_id ) );
}, 20, 2 );
add_action( 'woocommerce_order_status_changed', function( $order_id, $sen, $nauj, $order ) {
	if ( 'checkout-draft' === $sen ) petshop_priskirti_uzsakymo_nr( $order );
}, 20, 4 );
add_filter( 'woocommerce_order_number', function( $nr, $order ) {
	$m = $order instanceof WC_Order ? $order->get_meta( '_ps_order_number' ) : '';
	return $m ? (string) $m : $nr;
}, 10, 2 );
